				var oldLabels = fromSnap ? fromSnap.labels : null;
				if (oldLabels && p < 1) {
					children.push(
						h(
							"g",
							{ key: "xold", className: "thm-axisXOld", opacity: r2(1 - p) },
							oldLabels.map(function (lb) {
								return h("text", { key: "o" + lb.day, className: "thm-axisText thm-axisXFade", x: r2(lb.x), y: lb.y, textAnchor: lb.anchor, style: { fontSize: lb.fs + "px" } }, lb.text);
							}),
						),
					);
				}
				children.push(
					h(
						"g",
						{ key: "xnew", className: "thm-axisXNew", opacity: p < 1 ? r2(p) : 1 },
						geo.labels.map(function (lb) {
							return h("text", { key: "t" + lb.day, className: "thm-axisText thm-axisX", x: r2(lb.x), y: lb.y, textAnchor: lb.anchor, style: { fontSize: lb.fs + "px" } }, lb.text);
						}),
					),
				);
