							width: W,
							height: geo.H,
							role: "img",
							/* 观测钩子：DOM 里读到的就是画图用的同一套几何/domain，测试不必从像素反推 */
							"data-log": r2(geo.dom.lo) + "," + r2(geo.dom.hi),
							"data-plot": r2(geo.padL) + "," + r2(geo.padT) + "," + r2(geo.plotW) + "," + r2(geo.plotH),
