		/* ---------- ⑥ 模型用量环形图 ---------- */
		function donutCard(agg, rangeDays) {
			var size = 200;
			var cx = size / 2;
			var cy = size / 2;
			var radius = 68;
			var sw = 28;
			var circ = 2 * Math.PI * radius;
			var acc = 0;
			var segs = [];
			segs.push(h("circle", { key: "track", className: "thm-donutTrack", cx: cx, cy: cy, r: radius, strokeWidth: sw }));
			if (agg.total > 0) {
				agg.series.forEach(function (s) {
					if (s.total <= 0) return;
					var frac = s.total / agg.total;
					var len = frac * circ;
					segs.push(
						h("circle", {
							key: "seg" + s.name,
							/* ⚠️ 必须走 seriesClass()：与趋势图共用同一套系列色（「其他」= 中性灰），
							 * 旧代码写死 "thm-s" + (idx+1) → 第 4 项聚合「其他」拿到橙色，
							 * 和趋势图里真实模型 v4.1-pro 的橙色撞义 */
							className: "thm-donutSeg " + seriesClass(s),
							cx: cx,
							cy: cy,
							r: radius,
							strokeWidth: sw,
							strokeDasharray: r2(len) + " " + r2(Math.max(0, circ - len)),
							strokeDashoffset: r2(-acc * circ),
							transform: "rotate(-90 " + cx + " " + cy + ")",
						}),
					);
					acc += frac;
				});
			}
			var list = agg.total > 0
				? h(
						"ul",
						{ className: "thm-modelList" },
						agg.series.map(function (s2) {
							return h(
								"li",
								{ className: "thm-modelRow", key: s2.name, "data-model": s2.name },
								h("span", { className: "thm-dot " + seriesClass(s2) }),
								h("span", { className: "thm-modelName", title: s2.name }, shortModelName(s2.name)),
								h("span", { className: "thm-modelPct" }, fmtPctShort(agg.total > 0 ? s2.total / agg.total : null)),
								h("span", { className: "thm-modelVal" }, fmtCompact(s2.total) + " tokens"),
							);
						}),
					)
				: h("p", { className: "thm-status" }, "该区间没有模型用量记录。");
			return h(
				"section",
				{ className: "thm-card", key: "donut", "aria-label": "模型用量" },
				h(
					"div",
					{ className: "thm-cardHead" },
					h("h3", { className: "thm-h3" }, "模型用量"),
					/* 当前区间标记：环形图与趋势图吃同一个 rangeDays 过滤，但旧版只有趋势卡头写「近 N 日」，
					 * 环形图看不出来自己被过滤过 —— 标记挪到这张卡上，趋势卡头不再重复 */
					isNum(rangeDays) ? h("span", { className: "thm-rangeNow" }, "近 " + rangeDays + " 日") : null,
				),
				h(
					"div",
					{ className: "thm-donutBody" },
					h(
						"div",
						{ className: "thm-donutWrap" },
						h(
							"svg",
							{ className: "thm-donut", viewBox: "0 0 " + size + " " + size, width: size, height: size, role: "img", "aria-label": "模型用量占比环形图" },
							segs,
						),
						h(
							"div",
							{ className: "thm-donutCenter" },
							h("span", { className: "thm-donutVal" }, fmtCompact(agg.total)),
							h("span", { className: "thm-donutUnit" }, "tokens"),
						),
					),
					list,
				),
			);
		}

