					setBusy("");
					if (!blob) return;
					try {
						var f = new File([blob], "whale-voucher-NO." + voucherSerial(faceValue(tokens)) + ".png", { type: "image/png" });
						if (navigator.canShare && navigator.canShare({ files: [f] })) navigator.share({ files: [f], title: "Whale Voucher NO." + voucherSerial(faceValue(tokens)) });
					} catch (e) {}
