					var to = data.window.to;
					var from = addDays(to, -(rangeDays - 1));
					if (data.window.from && from < data.window.from) from = data.window.from;
					var dates = [];
					var n = diffDays(from, to) + 1;
					for (var d = 0; d < n; d++) dates.push(addDays(from, d));
